-- IMBOP Communications Infrastructure: first vertical slice\n-- EVENT -> COMMUNICATION -> IN-APP DELIVERY -> AUDIT\n\ncreate table if not exists public.communication_records (\n  id uuid primary key default gen_random_uuid(),\n  institution_id uuid references public.institutions(id) on delete set null,\n  recipient_user_id uuid references auth.users(id) on delete set null,\n  recipient_email text, recipient_name text,\n  sender_user_id uuid references auth.users(id) on delete set null,\n  origin text not null default 'SYSTEM' check (origin in ('SYSTEM','ADMIN')),\n  communication_type text not null, event_type text, subject text not null, body text not null,\n  reference_type text, reference_id uuid, metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists communication_records_recipient_user_idx on public.communication_records(recipient_user_id, created_at desc);\ncreate index if not exists communication_records_institution_idx on public.communication_records(institution_id, created_at desc);\ncreate index if not exists communication_records_reference_idx on public.communication_records(reference_type, reference_id);\n\ncreate table if not exists public.communication_deliveries (\n  id uuid primary key default gen_random_uuid(),\n  communication_id uuid not null references public.communication_records(id) on delete cascade,\n  channel text not null check (channel in ('IN_APP','EMAIL','SMS','WHATSAPP')),\n  status text not null default 'QUEUED' check (status in ('QUEUED','DELIVERED','READ','FAILED')),\n  attempted_at timestamptz, delivered_at timestamptz, read_at timestamptz, failure_reason text,\n  retry_count integer not null default 0 check (retry_count >= 0),\n  created_at timestamptz not null default now(), unique (communication_id, channel)\n);\ncreate index if not exists communication_deliveries_communication_idx on public.communication_deliveries(communication_id, channel);\ncreate index if not exists communication_deliveries_unread_idx on public.communication_deliveries(status, delivered_at desc);\n\nalter table public.communication_records enable row level security;\nalter table public.communication_deliveries enable row level security;\nrevoke all on table public.communication_records from anon, authenticated;\nrevoke all on table public.communication_deliveries from anon, authenticated;\ngrant select on table public.communication_records to authenticated;\ngrant select on table public.communication_deliveries to authenticated;\n\ndrop policy if exists communication_records_recipient_select on public.communication_records;\ncreate policy communication_records_recipient_select on public.communication_records for select to authenticated using ((select auth.uid()) = recipient_user_id or (select auth.uid()) = sender_user_id or private.has_platform_permission('institution_manage'));\ndrop policy if exists communication_deliveries_recipient_select on public.communication_deliveries;\ncreate policy communication_deliveries_recipient_select on public.communication_deliveries for select to authenticated using (exists (select 1 from public.communication_records c where c.id=communication_deliveries.communication_id and ((select auth.uid())=c.recipient_user_id or (select auth.uid())=c.sender_user_id or private.has_platform_permission('institution_manage'))));
create policy communication_deliveries_recipient_mark_read on public.communication_deliveries for update to authenticated using (exists (select 1 from public.communication_records c where c.id=communication_deliveries.communication_id and c.recipient_user_id=(select auth.uid()))) with check (status='READ' and exists (select 1 from public.communication_records c where c.id=communication_deliveries.communication_id and c.recipient_user_id=(select auth.uid())));\n\ncreate or replace function private.create_in_app_communication(p_institution_id uuid,p_recipient_user_id uuid,p_recipient_email text,p_recipient_name text,p_sender_user_id uuid,p_origin text,p_communication_type text,p_event_type text,p_subject text,p_body text,p_reference_type text,p_reference_id uuid,p_metadata jsonb default '{}'::jsonb)\nreturns uuid language plpgsql security definer set search_path to '' as $function$\ndeclare v_communication_id uuid;\nbegin\n  if p_recipient_user_id is null then return null; end if;\n  insert into public.communication_records(institution_id,recipient_user_id,recipient_email,recipient_name,sender_user_id,origin,communication_type,event_type,subject,body,reference_type,reference_id,metadata)\n  values(p_institution_id,p_recipient_user_id,p_recipient_email,p_recipient_name,p_sender_user_id,upper(coalesce(p_origin,'SYSTEM')),p_communication_type,p_event_type,p_subject,p_body,p_reference_type,p_reference_id,coalesce(p_metadata,'{}'::jsonb))\n  returning id into v_communication_id;\n  insert into public.communication_deliveries(communication_id,channel,status,attempted_at,delivered_at) values(v_communication_id,'IN_APP','DELIVERED',now(),now());\n  return v_communication_id;\nend; $function$;\n\ncreate or replace function public.get_my_communications(p_limit integer default 30,p_offset integer default 0)\nreturns table(id uuid,institution_id uuid,communication_type text,event_type text,subject text,body text,origin text,reference_type text,reference_id uuid,created_at timestamptz,delivery_id uuid,delivery_status text,delivered_at timestamptz,read_at timestamptz)\nlanguage sql security invoker set search_path to 'public' as $function$\n  select c.id,c.institution_id,c.communication_type,c.event_type,c.subject,c.body,c.origin,c.reference_type,c.reference_id,c.created_at,d.id,d.status,d.delivered_at,d.read_at\n  from public.communication_records c join public.communication_deliveries d on d.communication_id=c.id and d.channel='IN_APP'\n  where c.recipient_user_id=(select auth.uid()) order by c.created_at desc limit greatest(1,least(coalesce(p_limit,30),100)) offset greatest(0,coalesce(p_offset,0));\n$function$;\n\ncreate or replace function public.mark_communication_read(p_communication_id uuid)\nreturns jsonb language plpgsql security invoker set search_path to 'public' as $function$\ndeclare v_updated integer;\nbegin\n  if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;\n  update public.communication_deliveries d set status='READ',read_at=coalesce(read_at,now())\n  where d.communication_id=p_communication_id and d.channel='IN_APP' and exists (select 1 from public.communication_records c where c.id=d.communication_id and c.recipient_user_id=auth.uid());\n  get diagnostics v_updated=row_count; return jsonb_build_object('ok',v_updated=1,'updated',v_updated);\nend; $function$;\nrevoke execute on function public.get_my_communications(integer,integer) from anon;\ngrant execute on function public.get_my_communications(integer,integer) to authenticated;\nrevoke execute on function public.mark_communication_read(uuid) from anon;\ngrant execute on function public.mark_communication_read(uuid) to authenticated;\n\ncreate or replace function private.review_member_application_impl(p_application_id uuid,p_action text,p_notes text default null)\nreturns public.member_applications language plpgsql security definer set search_path to '' as $function$\ndeclare r public.member_applications; old_status text; new_status text; published_business_id uuid; business_owner_user_id uuid; v_business_name text;\nbegin\n  select * into r from public.member_applications where id=p_application_id for update;\n  if not found then raise exception 'Application not found'; end if;\n  old_status:=r.status; if not private.has_institution_permission(r.institution_id,'publication_manage') then raise exception 'Not authorized'; end if; p_action:=upper(trim(p_action));\n  if p_action='PUBLISH' then if r.status<>'PENDING_REVIEW' then raise exception 'PUBLISH requires PENDING_REVIEW'; end if; new_status:='PUBLISHED';\n  elsif p_action='RETURN' then if r.status<>'PENDING_REVIEW' then raise exception 'RETURN requires PENDING_REVIEW'; end if; new_status:='RETURNED';\n  elsif p_action='REJECT' then if r.status not in ('SUBMITTED','PENDING_REVIEW','RETURNED') then raise exception 'REJECT not allowed from current status'; end if; new_status:='REJECTED';\n  elsif p_action='REMOVE' then if r.status not in ('PUBLISHED','REJECTED','RETURNED') then raise exception 'REMOVE not allowed from current status'; end if; new_status:='REMOVED';\n  else raise exception 'Unsupported review action'; end if;\n  if p_action='REMOVE' then select mp.published_business_id into published_business_id from public.member_application_publications mp where mp.application_id=p_application_id for update; end if;\n  update public.member_applications set status=new_status,reviewed_at=now(),reviewed_by_user_id=auth.uid(),review_notes=p_notes,updated_at=now() where id=p_application_id returning * into r;\n  if p_action='PUBLISH' then\n    perform private.activate_member_application_publication(p_application_id);\n    select b.id,b.created_by_user_id,b.name into published_business_id,business_owner_user_id,v_business_name from public.member_application_publications mp join public.businesses b on b.id=mp.published_business_id where mp.application_id=p_application_id limit 1;\n    if business_owner_user_id is not null then\n      perform private.create_in_app_communication(r.institution_id,business_owner_user_id,r.email,r.applicant_name,auth.uid(),'SYSTEM','MEMBER_APPLICATION','MEMBER_APPLICATION_PUBLISHED','Your IMBOP business profile has been published','Your Institution has published your IMBOP business profile' || case when v_business_name is not null then ': ' || v_business_name else '' end || '. You can now use your IMBOP Space to present your business and opportunities.','member_application',p_application_id,jsonb_build_object('business_id',published_business_id,'status',new_status));\n    end if;\n  elsif p_action='REMOVE' and published_business_id is not null then perform private.unpublish_published_business(published_business_id,p_notes); end if;\n  insert into public.application_review_events(application_id,institution_id,action,from_status,to_status,actor_user_id,notes) values(p_application_id,r.institution_id,p_action,old_status,new_status,auth.uid(),p_notes);\n  return r;\nend; $function$;